\caption{Solve the Soft $k$-Means Problem \eqref{eq:SfM}}  
\label{alg:global}
\begin{algorithmic}[1]  
	\Require $\mathbf{X}\in\mathbb{R}^{d\times n}$ and the clusters number $k$
	\State $\overline{\mathbf{x}} \leftarrow \frac{1}{n}\mathbf{X}\mathbb{1}_n$
	\State $\mathbf{U}_{k-1}\leftarrow$  the $(k-1)$-truncated left SVs of $\mathbf{X}$
	\State $\mathbf{B} \leftarrow$ the $(k-1)$-truncated EVs of $\mathbf{H}_k$
	\State Ensure $r \geq \|\mathbf{U}_{k-1}^\top\mathbf{X} \|_{2,\infty}$
	\State $\mathbf{F}\leftarrow r\sqrt{k(k-1)}\mathbf{U}_{k-1}\mathbf{B}^\top + \overline{\mathbf{x}}\mathbb{1}_k^\top$
	\State $\mathbf{G}^\top \leftarrow \frac{1}{r\sqrt{k(k-1)}}\mathbf{BU}_{k-1}^\top \mathbf{X} + \frac{1}{k}\mathbb{1}_k\mathbb{1}_n^\top$
	\Ensure Prototypes $\mathbf{F} \in \mathbb{R}^{d\times k}$, membership $\mathbf{G} \in \mathbb{R}^{k \times n}$

	\label{code:recentEnd}  
\end{algorithmic}

\label{lem:numerical}
	Let $\mathbf{x} \in \mathbb{R}^k$.
	If $\mathbb{1}_k^\top\mathbf{x}=0$ and $\|\mathbf{x}\|_2 \leq 1$, then we have $\|\mathbf{x}\|_\infty \leq \frac{\sqrt{k(k-1)}}{k}.$

\label{remark:proof_sketch_unique}
	Corollary \ref{thm:mainCorollary} shows that the output $\mathbf{F}$ and $\mathbf{G}$ by Algorithm \ref{alg:global}
	are an optimal solution of Problem \eqref{eq:SfM}. But we note that the solution of Problem \eqref{eq:SfM}
	is not unique since for the matrix $\mathbf{B}\in\mathbb{R}^{k\times (k-1)}$ defined in Algorithm \ref{alg:global} as
	the $(k-1)$-truncated eigenvectors of centralization matrix $\mathbf{H}_k$ is not unique. Indeed, for any $\mathbf{B}$, 
	matrix $\mathbf{BR}$ is still $(k-1)$-truncated eigenvectors of centralization matrix $\mathbf{H}_k$, where $\mathbf{R}^\top\mathbf{R}=\mathbb{I}_{(k-1)}$.
	That reveals there is non-uniqueness in the solution set of the Problem \eqref{eq:SfM}.
	Indeed, we develop a lower bound (\Cref{sec:arbitray}) on the distance between oracle $\mathbf{G}^*$ and the solution of Problem \eqref{eq:SfM} in Frobenius norm.


\caption{Solve the MVS$k$M Problem}  
\label{alg:MVSfM}
\begin{algorithmic}[1]  
	\Require $\mathbf{X}\in\mathbb{R}^{d\times n}$, $\lambda$, and the clusters number $k$
	\State $\mathbf{F}_0 \leftarrow$ random initialized prototypes.
	\Repeat
	\State $\mathbf{V}_t \leftarrow$ left SV of $\mathbf{F}_t$
	\State $\mathbf{D}_t \leftarrow\mathbf{V}_t \text{diag}(\{ 1/(\sigma_i^2(\mathbf{F}_t) + \varepsilon) \}_{i=1}^k) \mathbf{V}_t^\top$
	\State $\mathbf{F}_{t+1} \leftarrow \mathbf{X}\mathbf{G}_t(\mathbf{G}_t^\top\mathbf{G}_t + \lambda \mathbf{D}_t)^{-1}$
	\State $\displaystyle \mathbf{G}_{t+1} \leftarrow \mathop{\arg\min}_{\mathbf{G}\succeq 0,\mathbf{G}\mathbb{1}_k = \mathbb{1}_n} \| \mathbf{X} - \mathbf{F}_{t+1}\mathbf{G}^\top\|_F^2.$
	\Until{converge}

	\Ensure Prototypes $\mathbf{F} \in \mathbb{R}^{d\times c}$, membership $\mathbf{G} \in \mathbb{R}^{c \times n}$.
\end{algorithmic}

